func Or(predicates ...predicate.Mysekaiitem) predicate.Mysekaiitem {
	return predicate.Mysekaiitem(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Mysekaiitem) predicate.Mysekaiitem {
	return predicate.Mysekaiitem(sql.NotPredicates(p))
}
